sp_instance.css:
{
  "html": {
    "value": "<style>
.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  background-color: #01b4e4; /* modrá TMDB */
  color: white;
  font-family: Arial, sans-serif;
}
.header-left img {
  height: 50px;
}
.header-center nav a {
  margin: 0 15px;
  color: white;
  text-decoration: none;
  font-weight: bold;
}
.header-center nav a:hover {
  text-decoration: underline;
}
.header-right input.search-input {
  padding: 5px 10px;
  border-radius: 4px;
  border: none;
  margin-right: 5px;
}
.header-right button.search-btn {
  padding: 5px 10px;
  background-color: #90cea1;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
}
.header-right button.search-btn:hover {
  background-color: #76b38f;
}
</style>

<div class="header-container">
  <div class="header-left">
    <img src="https://via.placeholder.com/150x50?text=Movie+Explorer" alt="Movie Explorer Logo">
  </div>
  <div class="header-center">
    <nav class="header-nav">
      <a href="#">Movies</a>
      <a href="#">Actors</a>
      <a href="#">Genres</a>
      <a href="#">Reviews</a>
    </nav>
  </div>
  <div class="header-right">
    <input type="text" placeholder="Search movies..." class="search-input">
    <button class="search-btn">Search</button>
  </div>
</div>",
    "displayValue": "Header pre Movie Explorer"
  }
}

